// Generated by `python -m schema.export` from schema/claim.py. Do not edit by hand.
// A test fails when this file is stale.

export interface Source {
  kind: "file" | "url" | "api" | "video";
  /** Path inside the data room, a URL, or the API call. */
  uri: string;
  /** For example 'slide 3', 'page 2', 'ARR_Build!E14', 'ARR_TOTAL', 'clause 7', 'line 12', 'row 118', 't=35-41'. */
  locator: string;
  /** Video only. Copied from the transcript by the script. */
  start_s: number | null;
  /** Video only. Copied from the transcript by the script. */
  end_s: number | null;
  /** The exact span relied on, copied character for character. */
  quote: string;
  /** ISO date the source was read. */
  retrieved_at: string | null;
}

export interface Value {
  number: number;
  unit: "USD" | "USD_per_month" | "USD_per_year" | "percent" | "months" | "days" | "accounts" | "count";
  label: "arr" | "mrr" | "paying_accounts" | "accounts_created" | "nrr_12m" | "grr_12m" | "cohort_size" | "gross_margin" | "cost_of_revenue" | "runway_months" | "net_burn_monthly" | "payroll_monthly" | "hires" | "headcount" | "cash" | "largest_customer_share" | "top3_customer_share" | "arpa" | "acv" | "cac" | "payback_months" | "ltv" | "raise_amount" | "pre_money" | "post_money" | "ownership" | "tam" | "sam" | "som" | "price" | "contract_term" | "notice_period" | "signal" | "other";
  /** The month or span the number is for, for example '2026-09'. */
  period: string | null;
}

export interface Check {
  kind: "script" | "model";
  /** The entry's check name, plus '.read' for a model claim. */
  name: string;
  /** Model id. The model sets null; the script fills it. */
  model: string | null;
}

export interface Claim {
  /** Unique inside the scan, for example 'redflags-004'. */
  id: string;
  scan: string;
  /** The one plain sentence the readout shows. Judged claims start with 'Reading:'. */
  text: string;
  value: Value | null;
  /** The model sets null; the script sets it from the label. */
  severity: "info" | "watch" | "flag" | null;
  check: Check;
  confidence: "computed" | "quoted" | "judged" | "unverified";
  /** At least one. A missing input is a Gap, never a claim. */
  sources: Source[];
  /** Ids of claims that state a different number for the same label, unit and period. */
  conflicts_with: string[];
  /** Ids of claims from an independent source that agree within tolerance. The memo fills it; a scan leaves it empty. */
  corroborated_by: string[];
}

export interface Gap {
  /** Starts with 'Not in the room:' and names what is missing. */
  what: string;
  /** For example 'file missing', 'tab missing', 'Akta plan returns 403', 'not stated in the file'. */
  why: string;
  /** The document or source that would close the gap. */
  would_need: string;
  /** The piece the gap feeds. The scan sets it when it knows; the memo fills the rest. */
  piece: "traction_and_revenue" | "retention" | "burn_and_runway" | "unit_economics" | "customers" | "market" | "comps" | "team" | "the_pitch_itself" | null;
}

export interface Panel {
  /** For example 'comps table', 'signals grid', 'video moments'. */
  name: string;
  columns: string[];
  rows: string[][];
}

export interface Piece {
  name: "traction_and_revenue" | "retention" | "burn_and_runway" | "unit_economics" | "customers" | "market" | "comps" | "team" | "the_pitch_itself";
  verdict: "looking_strong" | "looking_weak" | "mixed" | "not_enough_in_the_room";
  /** One line, with its number and source. */
  reason: string;
  reason_claim_ids: string[];
  /** Every claim in the piece, for the drill-down. */
  claim_ids: string[];
  corroborating_sources: number;
  contradicting_sources: number;
  status: "done" | "running" | "waiting_on_input";
  /** Inputs the piece still needs, such as 'financial model'. */
  waiting_on: string[];
}

export interface TopFlag {
  kind: "green" | "red";
  piece: "traction_and_revenue" | "retention" | "burn_and_runway" | "unit_economics" | "customers" | "market" | "comps" | "team" | "the_pitch_itself";
  /** 1 is the strongest green or the worst red. */
  rank: number;
  text: string;
  claim_ids: string[];
}

export interface AskItem {
  /** What to request, in words the operator can paste into an email. */
  what: string;
  /** The claim or gap it would settle, with its number. */
  why: string;
  piece: "traction_and_revenue" | "retention" | "burn_and_runway" | "unit_economics" | "customers" | "market" | "comps" | "team" | "the_pitch_itself";
  from_kind: "gap" | "weak_piece" | "checklist";
  claim_ids: string[];
  /** For example 'C29', when the line comes from a missing checklist item. */
  checklist_id: string | null;
  /** True when the item is only 'lighter' at the company's stage. */
  if_you_have_it: boolean;
}

/** What every scan writes: one file, out/<room>/<scan>.json. */
export interface ScanResult {
  scan: string;
  room: string;
  ran_at: string;
  /** Files and calls the scan read. */
  inputs: string[];
  claims: Claim[];
  gaps: Gap[];
  /** Optional named tables the page shows beside the claims. */
  panels: Panel[];
}

/** One plain sentence from the operator on a piece or a line. */
export interface Steer {
  piece: "traction_and_revenue" | "retention" | "burn_and_runway" | "unit_economics" | "customers" | "market" | "comps" | "team" | "the_pitch_itself";
  /** Tricorder tells the two apart from the sentence; the operator never picks. */
  kind: "rewrite" | "more_info";
  instruction: string;
  /** The line the operator typed on, when it was a line and not the whole piece. */
  claim_id: string | null;
  at: string;
  author: string | null;
}

export interface PieceRevision {
  steer: Steer;
  before: Piece;
  after: Piece;
  claims_added: string[];
  sources_added: string[];
  claims_dropped: string[];
  verdict_moved_by: string[];
  /** For example why a requested number change was not carried out. */
  note: string | null;
}

/** One line of eval/score.py against an answer key. */
export interface ScoreLine {
  room: string;
  found: number;
  planted: number;
  decoys_flagged: number;
  decoys: number;
}

/** out/<room>/readout.json: what the page renders, in the order it shows it. */
export interface Readout {
  room: string;
  built_at: string;
  /** Shown as a banner on every screen when set. */
  synthetic_notice: string | null;
  top_flags: TopFlag[];
  pieces: Piece[];
  claims: Claim[];
  /** The 'could not verify' box. */
  unverified: Claim[];
  gaps: Gap[];
  asks: AskItem[];
  panels: Panel[];
  scans_run: string[];
  scans_missing: string[];
  revisions: PieceRevision[];
  /** The memo pass's connecting sentences, each citing claim ids. */
  connecting: string[];
  scores: ScoreLine[];
}
